package com.svc.voice;
import android.content.Context;
import android.media.*;
import java.io.*;
import java.nio.file.*;
import java.util.*;
import java.util.concurrent.*;
import java.util.zip.*;
import org.json.*;
public final class LocalHttpApi implements LocalHttpWire.Handler,AutoCloseable {
    /** 设备 SoC/HTP 结论；用反射取，便于测试桩环境与旧 Engine 共存 */
    private static String socText() {
        try {
            java.lang.reflect.Method m = Engine.class.getMethod("socReport");
            Object v = m.invoke(null);
            return v == null ? "unknown|unknown|unknown-arch" : String.valueOf(v);
        } catch (Throwable t) { return "unknown|unknown|unknown-arch"; }
    }
 private UploadStore uploads;
 private final Prefs prefs; private final RoleStore roles; private final File work;
 private final ExecutorService worker=Executors.newSingleThreadExecutor();
 private final LinkedHashMap<String,Task> tasks=new LinkedHashMap<>();
 private String owner; private Task active; private boolean closed;
 private static class Failure extends Exception {final int code;Failure(int c,String s){super(s);code=c;}}
 private static class Task {String id=UUID.randomUUID().toString(),kind,role,device;int frames,buffer,pitch,threads;boolean denoise,volumeLimit;File dir,input,output;volatile String state="queued",error="";volatile boolean cancel;volatile int done,total;}
 public LocalHttpApi(Context c){prefs=new Prefs(c);Tune.init(c);try{roles=new RoleStore(new File(prefs.rolesDir()));work=Files.createTempDirectory(c.getCacheDir().getCanonicalFile().toPath(),"http-api-").toFile();uploads=new UploadStore(new File(c.getFilesDir().getCanonicalFile(),"http-uploads-v1"),()->{final String token;try{token=lock();}catch(Failure e){if(e.code==409)return null;throw e;}return new UploadStore.Lease(){public Object importFile(File zip,String name,UploadStore.Cancellation cancel)throws Exception{return importZip(zip,name,cancel);}public void close(){unlock(token);}};});}catch(IOException e){throw new IllegalStateException(e);}}
 public synchronized boolean busy(){return owner!=null;}
 private synchronized String lock()throws Failure{if(closed)throw new Failure(409,"API closed");String t="http:"+UUID.randomUUID();if(owner!=null||!Busy.acquire(t))throw new Failure(409,"Engine busy");owner=t;return t;}
 private synchronized void unlock(String t){if(t.equals(owner)){active=null;owner=null;Busy.release(t);notifyAll();}}
 private static JSONObject json(Object... a)throws JSONException{JSONObject o=new JSONObject();for(int i=0;i<a.length;i+=2)o.put((String)a[i],a[i+1]);return o;}
 private static LocalHttpWire.Reply reply(int c,Object o){return new LocalHttpWire.Reply(c,o.toString());}
 private static String field(LocalHttpWire.Request r,String k,String d){String s=r.fields.get(k);return s==null?d:s;}
 private static int num(LocalHttpWire.Request r,String k,int d,int lo,int hi)throws Failure{try{int n=Integer.parseInt(field(r,k,""+d));if(n<lo||n>hi)throw new NumberFormatException();return n;}catch(NumberFormatException e){throw new Failure(400,k+" must be "+lo+".."+hi);}}
 private static boolean bool(LocalHttpWire.Request r,String k,boolean d)throws Failure{String s=field(r,k,""+d);if(!s.equals("true")&&!s.equals("false"))throw new Failure(400,k+" must be true or false");return Boolean.parseBoolean(s);}
 private File resolve(String n)throws Failure{try{return roles.resolve(n);}catch(IOException e){throw new Failure(400,e.getMessage());}}
 private File role(String n)throws Failure{File f=resolve(n);if(!f.isDirectory()||!new File(f,"dec.onnx").isFile())throw new Failure(404,"Role not found");try(java.util.stream.Stream<Path> paths=Files.walk(f.toPath())){if(paths.anyMatch(Files::isSymbolicLink))throw new Failure(400,"Role contains symbolic link");}catch(IOException e){throw new Failure(400,"Unreadable role");}return f;}
 private static File upload(LocalHttpWire.Request r)throws Failure{File f=r.files.get("file");if(f==null||!f.isFile())throw new Failure(400,"multipart file required");return f;}
 public LocalHttpWire.Reply handle(LocalHttpWire.Request r){try{synchronized(this){if(closed)throw new Failure(409,"API closed");}return route(r);}catch(Exception e){try{int code=e instanceof Failure?((Failure)e).code:500;return reply(code,json("error",json("code",code,"message",code==500?"Internal server error":String.valueOf(e.getMessage()))));}catch(Exception ignored){return reply(500,"{}");}}}
 private LocalHttpWire.Reply route(LocalHttpWire.Request r)throws Exception{
 String p=r.path,m=r.method;
 if(p.equals("/api/v1/uploads")||p.startsWith("/api/v1/uploads/"))return uploads.handle(r);
 if(p.equals("/api/v1/roles")&&m.equals("GET")){JSONArray a=new JSONArray();for(File f:roles.list())a.put(json("name",f.getName(),"compiled",new JSONArray(Engine.listCompiled(f))));return reply(200,json("roles",a));}
 if(p.equals("/api/v1/roles/import")&&m.equals("POST"))return importRole(r);
 if(p.equals("/api/v1/config")&&m.equals("PUT")){String token=lock();try{boolean n=bool(r,"npu",prefs.device().equals("npu"));int t=num(r,"threads",prefs.cpuThreads(),1,8);Engine.release();prefs.setDevice(n?"npu":"cpu");prefs.setCpuThreads(t);Engine.device=prefs.device();MainActivity.modelReady=false;if(!prefs.roleDir().isEmpty()){Engine engine=Engine.acquire(prefs.modelsDir(),this::log);engine.loadRole(prefs.roleDir(),prefs.fileFrames());MainActivity.modelReady=true;}return reply(200,json("npu",n,"threads",t,"soc",socText()));}finally{unlock(token);}}
 if(p.equals("/api/v1/logs")){if(m.equals("GET"))return reply(200,json("log",AppLog.tail(prefs.baseDir())));if(m.equals("DELETE")){String token=lock();try{synchronized(AppLog.class){try(RandomAccessFile f=new RandomAccessFile(new File(prefs.baseDir(),"app.log"),"rw")){f.setLength(0);}AppLog.generation++;AppLog.revision++;}return reply(200,json("cleared",true));}finally{unlock(token);}}}
 if(p.startsWith("/api/v1/roles/")){String[] a=p.substring(14).split("/",-1);
 if(a.length==1&&m.equals("DELETE")){String token=lock();try{File f=role(a[0]);Engine.release();RoleStore.deleteTree(f);return reply(200,json("deleted",true));}finally{unlock(token);}}
 if(a.length==2&&a[1].equals("compilations")&&(m.equals("POST")||m.equals("DELETE"))){String token=lock();boolean handed=false;try{File f=role(a[0]);int frames=num(r,"frames",256,1,2584);Engine.release();if(m.equals("DELETE")){File[] fs=f.listFiles();if(fs!=null)for(File x:fs)if(x.getName().equals("dec_ctx_"+frames+".onnx")||x.getName().startsWith("dec_ctx_"+frames+".onnx."))RoleStore.deleteTree(x);return reply(200,json("deleted",true));}int st=Engine.readStaticT(new File(f,"dec.onnx"));if(st>0&&st!=frames)throw new Failure(400,"Static decoder requires frames="+st);Task t=task("compile",a[0],frames);submit(t,token);handed=true;return reply(202,status(t));}finally{if(!handed)unlock(token);}}
 }
 if(p.equals("/api/v1/tasks")&&m.equals("POST")){String token=lock();boolean handed=false;Task t=null;try{String name=field(r,"role","");role(name);int frames=num(r,"frames",256,1,2584);t=task("convert",name,frames);t.buffer=num(r,"bufferFrames",Math.min(16,frames/2),0,frames/2);t.pitch=num(r,"pitchSemitones",0,-24,24);t.denoise=bool(r,"denoise",false);t.volumeLimit=bool(r,"volumeLimit",false);if(!t.dir.mkdirs())throw new IOException("Cannot create task directory");t.input=new File(t.dir,"input");Files.copy(upload(r).toPath(),t.input.toPath());duration(t.input);submit(t,token);handed=true;return reply(202,status(t));}finally{if(!handed){if(t!=null)clean(t.dir);unlock(token);}}}
 if(p.startsWith("/api/v1/tasks/")){String[] a=p.substring(14).split("/",-1);Task t;synchronized(this){t=tasks.get(a[0]);}if(t==null)throw new Failure(404,"Task not found");if(a.length==1&&m.equals("GET"))return reply(200,status(t));if(a.length==2&&a[1].equals("result")&&m.equals("GET")){if(!t.state.equals("succeeded")||t.output==null)throw new Failure(409,"Result unavailable");return LocalHttpWire.Reply.file(t.output,"audio/wav");}if(a.length==2&&a[1].equals("cancel")&&m.equals("POST")){synchronized(this){if(!t.kind.equals("convert"))throw new Failure(409,"Compilation cannot be cancelled");if(active==t&&owner!=null&&owner.equals(Busy.holder())&&!terminal(t)){t.cancel=true;JobService.cancelReq=true;}}return reply(200,status(t));}}
 throw new Failure(404,"Route not found");
 }
 private Task task(String k,String r,int f){Task t=new Task();t.kind=k;t.role=r;t.frames=f;t.device=prefs.device();t.threads=prefs.cpuThreads();t.dir=new File(work,t.id);return t;}
 private static boolean terminal(Task t){return t.state.equals("succeeded")||t.state.equals("failed")||t.state.equals("cancelled");}
 private JSONObject status(Task t)throws JSONException{return json("id",t.id,"kind",t.kind,"state",t.state,"role",t.role,"frames",t.frames,"bufferFrames",t.buffer,"pitchSemitones",t.pitch,"denoise",t.denoise,"volumeLimit",t.volumeLimit,"npu",t.device.equals("npu"),"threads",t.threads,"done",t.done,"total",t.total,"cancelRequested",t.cancel,"error",t.error);}
 private synchronized void submit(Task t,String token)throws Failure{if(closed)throw new Failure(409,"API closed");while(tasks.size()>=16){Iterator<Task> i=tasks.values().iterator();Task old=i.next();clean(old.dir);i.remove();}tasks.put(t.id,t);active=t;if(t.kind.equals("convert")){JobService.cancelReq=false;JobService.paused=false;}try{worker.execute(()->run(t,token));}catch(RuntimeException e){tasks.remove(t.id);active=null;throw e;}}
 private void run(Task t,String token){t.state="running";try{Engine.release();if(t.kind.equals("compile"))Engine.compileNpuContext(role(t.role),t.frames,this::log);else{check(t);duration(t.input);float[] in=AudioIO.decode(t.input.getAbsolutePath(),Engine.SR_IN);if(in.length==0||in.length>120L*Engine.SR_IN)throw new Failure(400,"Audio exceeds 120 seconds or is empty");check(t);Engine.device=t.device;Engine e=Engine.acquire(prefs.modelsDir(),this::log);e.loadRole(role(t.role).getAbsolutePath(),t.frames);if(e.frames()!=t.frames)throw new Failure(400,"Unsupported role frames");Pipeline.fileDenoise.set(t.denoise);Pipeline.fileVolumeLimit.set(t.volumeLimit);Pipeline.filePitch.set(t.pitch);Pipeline.audioProgress.set((d,n)->check(t));float[] out=Pipeline.process(e,in,t.buffer,(d,n,s)->{check(t);t.done=d;t.total=n;});check(t);t.output=new File(t.dir,"result.wav");AudioIO.writeWav(t.output.getAbsolutePath(),out,Engine.SR_OUT);check(t);}synchronized(this){check(t);t.state="succeeded";}}catch(Throwable e){t.error=String.valueOf(e.getMessage());t.state=t.cancel?"cancelled":"failed";clean(t.output);log("HTTP task "+t.id+": "+t.state+" "+t.error);}finally{Pipeline.fileDenoise.remove();Pipeline.fileVolumeLimit.remove();Pipeline.filePitch.remove();Pipeline.audioProgress.remove();try{Engine.release();}finally{clean(t.input);synchronized(this){if(t.kind.equals("convert")&&active==t&&token.equals(Busy.holder())){JobService.cancelReq=false;JobService.paused=false;}unlock(token);}}}}
 private static void check(Task t){if(t.cancel)throw new RuntimeException("__CANCELLED__");}
 private void log(String s){AppLog.i(prefs.baseDir(),s);}
 private static void duration(File f)throws Exception{MediaExtractor e=new MediaExtractor();try{e.setDataSource(f.getAbsolutePath());boolean found=false;for(int i=0;i<e.getTrackCount();i++){MediaFormat m=e.getTrackFormat(i);String mime=m.getString(MediaFormat.KEY_MIME);if(mime!=null&&mime.startsWith("audio/")){found=true;if(!m.containsKey(MediaFormat.KEY_DURATION)||m.getLong(MediaFormat.KEY_DURATION)<=0||m.getLong(MediaFormat.KEY_DURATION)>120000000L)throw new Failure(400,"Audio duration must be known and <=120 seconds");}}if(!found)throw new Failure(400,"No audio track");}catch(IOException|IllegalArgumentException x){throw new Failure(400,"Invalid audio");}finally{e.release();}}
 private LocalHttpWire.Reply importRole(LocalHttpWire.Request r)throws Exception{String token=lock();File tmp=null,stage=null;try{String name=field(r,"name","");File out=resolve(name);if(out.exists())throw new Failure(409,"Role exists");tmp=Files.createTempDirectory(work.toPath(),"import-").toFile();unzip(upload(r),tmp);File source=find(tmp);if(source==null)throw new Failure(400,"No pth/pt model in ZIP");stage=Files.createTempDirectory(new File(prefs.rolesDir()).toPath(),".http-import-").toFile();try{RoleImporter.importRole(source,stage,new File(prefs.baseDir(),"tpl"),this::log);}catch(IOException e){throw new Failure(400,"Import failed: invalid or incompatible role model");}Engine.release();if(!stage.renameTo(out))throw new IOException("Cannot publish role");stage=null;return reply(201,json("name",name));}finally{clean(tmp);clean(stage);unlock(token);}}
 private Object importZip(File zip,String name,UploadStore.Cancellation cancel)throws Exception {File tmp=null,stage=null;try{File out=resolve(name);if(out.exists()){File marker=new File(out,".http-upload-id");if(marker.isFile()&&new String(Files.readAllBytes(marker.toPath()),java.nio.charset.StandardCharsets.UTF_8).equals(cancel.uploadId()))return json("name",name);throw new Failure(409,"Role exists");}cancel.check();tmp=Files.createTempDirectory(work.toPath(),"import-").toFile();unzip(zip,tmp);cancel.check();File source=find(tmp);if(source==null)throw new Failure(400,"No pth/pt model in ZIP");stage=Files.createTempDirectory(new File(prefs.rolesDir()).toPath(),".http-import-").toFile();final UploadStore.Cancellation check=cancel;RoleImporter.importRole(source,stage,new File(prefs.baseDir(),"tpl"),msg->{try{check.check();}catch(IOException e){throw new RuntimeException(e);}log(msg);});if(treeSize(stage)>4294967296L)throw new IOException("Import staging exceeds 4 GiB");cancel.check();Files.write(new File(stage,".http-upload-id").toPath(),cancel.uploadId().getBytes(java.nio.charset.StandardCharsets.UTF_8));Engine.release();final File publish=stage;cancel.commit(()->{if(out.exists()||!publish.renameTo(out))throw new IOException("Cannot publish role");});stage=null;return json("name",name);}finally{clean(tmp);clean(stage);}}
 private static long treeSize(File d)throws IOException {long n=0;try(java.util.stream.Stream<Path> paths=Files.walk(d.toPath())){Iterator<Path> it=paths.iterator();while(it.hasNext()){Path p=it.next();if(Files.isRegularFile(p))n=Math.addExact(n,Files.size(p));}}return n;}
 private static File find(File d){File[] fs=d.listFiles();if(fs==null)return null;for(File f:fs)if(f.isFile()&&(f.getName().toLowerCase(Locale.ROOT).endsWith(".pth")||f.getName().toLowerCase(Locale.ROOT).endsWith(".pt")))return d;for(File f:fs)if(f.isDirectory()){File v=find(f);if(v!=null)return v;}return null;}
 private static void unzip(File zip,File dest)throws Exception{long total=0;int count=0;String root=dest.getCanonicalPath()+File.separator;Set<String> seen=new HashSet<>();try(ZipFile z=new ZipFile(zip)){Enumeration<? extends ZipEntry> es=z.entries();byte[] b=new byte[65536];while(es.hasMoreElements()){ZipEntry e=es.nextElement();String n=e.getName();if(n.split("/",-1).length>64)throw new Failure(400,"ZIP nesting limit 64");if(++count>4096)throw new Failure(400,"ZIP entry limit 4096");if(n.startsWith("/")||n.contains("\\")||n.indexOf(0)>=0||n.matches("^[A-Za-z]:.*"))throw new Failure(400,"Unsafe ZIP path");File f=new File(dest,n);String cp=f.getCanonicalPath();if(!cp.startsWith(root)||!seen.add(cp))throw new Failure(400,"Unsafe or duplicate ZIP path");long compressed=e.getCompressedSize();if(!e.isDirectory()&&(e.getSize()<0||e.getSize()>dest.getUsableSpace()-67108864L))throw new Failure(400,"Insufficient disk space for ZIP");if(compressed<0||e.getSize()>4294967296L||e.getSize()>Math.max(1,compressed)*200L)throw new Failure(400,"ZIP size/ratio limit");if(e.isDirectory()){if(!f.isDirectory()&&!f.mkdirs())throw new IOException("mkdir");continue;}if(!f.getParentFile().isDirectory()&&!f.getParentFile().mkdirs())throw new IOException("mkdir");long size=0;try(InputStream in=z.getInputStream(e);OutputStream out=new FileOutputStream(f)){int len;while((len=in.read(b))!=-1){size+=len;total+=len;if(size>4294967296L||total>8589934592L||size>Math.max(1,compressed)*200L)throw new Failure(400,"ZIP expansion limit");out.write(b,0,len);}}}}catch(ZipException e){throw new Failure(400,"Invalid ZIP");}}
 private static void clean(File f){try{RoleStore.deleteTree(f);}catch(IOException ignored){}}
 /** Stop listener first; call off main thread and keep foreground until this returns. */
 public void close(){synchronized(this){closed=true;if(active!=null&&active.kind.equals("convert")&&!terminal(active)&&owner!=null&&owner.equals(Busy.holder())){active.cancel=true;JobService.cancelReq=true;}worker.shutdown();}uploads.close();boolean interrupted=false;for(;;){try{if(worker.awaitTermination(1,TimeUnit.SECONDS))break;}catch(InterruptedException e){interrupted=true;}}synchronized(this){while(owner!=null)try{wait();}catch(InterruptedException e){interrupted=true;}clean(work);tasks.clear();}if(interrupted)Thread.currentThread().interrupt();}
}
